    //      0 0 d1 0 0 d2 0 0 d3 0 0 d4;
    //      c1 b1 0 c2 b2 0 c3 b3 0 c4 b4 0;
    //      0 d1 c1 0 d2 c2 0 d3 c3 0 d4 c4;
