    // because H_inv * [1,x,y,z]^T gives the shape function values

    // Build B matrix (6x12)
    Eigen::Matrix<double, 6, 12> B = Eigen::Matrix<double, 6, 12>::Zero();
    for (int i = 0; i < 4; ++i) {
