        // These are H_inv(1,i), H_inv(2,i), H_inv(3,i) respectively
        double bi = H_inv(1, i);  // dN_i/dx
        double ci = H_inv(2, i);  // dN_i/dy
        double di = H_inv(3, i);  // dN_i/dz

        // Row 0: dN_i/dx for ux components → ∂u/∂x
        B(0, col_base + 0) = bi;
        // Row 1: dN_i/dy for uy components → ∂v/∂y
        B(1, col_base + 1) = ci;
        // Row 2: dN_i/dz for uz components → ∂w/∂z
        B(2, col_base + 2) = di;
        // Row 3: dN_i/dy, dN_i/dx for exy = ∂u/∂y + ∂v/∂x
        B(3, col_base + 0) = ci;  // ∂u/∂y
        B(3, col_base + 1) = bi;  // ∂v/∂x
        // Row 4: dN_i/dz, dN_i/dy for eyz = ∂v/∂z + ∂w/∂y
        B(4, col_base + 1) = di;  // ∂v/∂z
        B(4, col_base + 2) = ci;  // ∂w/∂y
        // Row 5: dN_i/dz, dN_i/dx for ezx = ∂w/∂x + ∂u/∂z ← FIXED: swapped columns corrected
        B(5, col_base + 0) = di;  // ∂u/∂z → acts on u_i (col_base+0)
        B(5, col_base + 2) = bi;  // ∂w/∂x → acts on w_i (col_base+2)
    }

    // Compute stiffness matrix: K = B^T * D * B * volume
    Eigen::Matrix<double, 12, 12> K_standard = B.transpose() * G * B * volume;

    // Output as JSON
    std::cout << "{\"stiffness_matrix\":[";
    for (int i = 0; i < 12; ++i) {
        std::cout << "[";
        for (int j = 0; j < 12; ++j) {
            std::cout << std::scientific << std::setprecision(6) << K_standard(i, j);
            if (j < 11) std::cout << ",";
        }
        std::cout << "]";
        if (i < 11) std::cout << ",";
    }
    std::cout << "]}" << std::endl;

    return 0;
}

